    'finance.cash.recorded':['Vastgelegde kasbeweging: {actual}; planning tot hetzelfde moment: {planned}; afwijking: {variance}','Recorded cash movement: {actual}; plan to the same point: {planned}; variance: {variance}','Erfasste Zahlungsbewegung: {actual}; Planung bis zum selben Zeitpunkt: {planned}; Abweichung: {variance}','Mouvement de trésorerie enregistré : {actual} ; prévision au même moment : {planned} ; écart : {variance}','Movimiento de tesorería registrado: {actual}; previsión hasta el mismo momento: {planned}; desviación: {variance}','Registreret likviditetsbevægelse: {actual}; plan til samme tidspunkt: {planned}; afvigelse: {variance}','Registrert kontantbevegelse: {actual}; plan til samme tidspunkt: {planned}; avvik: {variance}','Registrerat kassaflöde: {actual}; plan till samma tidpunkt: {planned}; avvikelse: {variance}'],
